-- Dashboard Admin: todos os números num só pedido, calculados no servidor.
-- Nível 'total' recebe tudo; nível 'comercial' recebe só o controlo comercial (objetivos, comissões, bónus).

create or replace function private.opera_j(q text) returns jsonb
language plpgsql stable set search_path = public as $$
declare r jsonb;
begin
  execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from (%s) x', q) into r;
  return r;
end $$;
revoke all on function private.opera_j(text) from public, anon, authenticated;

create or replace function public.opera_admin_dados(p_inicio date, p_fim date) returns jsonb
language plpgsql stable security definer set search_path = public as $fn$
declare
  v_nivel text := private.opera_nivel();
  i text := quote_literal(coalesce(p_inicio, date_trunc('month', current_date)::date));
  f text := quote_literal(coalesce(p_fim, current_date));
  par text;
  ana jsonb;
  out jsonb;
begin
  if v_nivel is null then raise exception 'Sem acesso ao Dashboard Admin.'; end if;
  if p_inicio is not null and p_fim is not null and p_inicio > p_fim then raise exception 'Período inválido.'; end if;
  par := format('par as (select %s::date i, %s::date f)', i, f);

  -- Controlo comercial da Ana
  ana := jsonb_build_object(
    'ana_controlo', private.opera_j($q$
with per as ( select g::date fim from generate_series(date '2026-11-25', (date_trunc('month', current_date) + interval '3 months 24 days')::date, interval '1 month') g ),
p as ( select fim, greatest((fim - interval '1 month' + interval '1 day')::date, date '2026-11-09') inicio from per ),
ana as ( select user_id id from opera_admin_acessos where vendedor ilike 'Ana%' ),
vend as ( select c.*, case when c.modalidade = 3 and opera_preco_tabela(c.servico,1) is not null and c.valor_total > opera_preco_tabela(c.servico,1) * c.duracao_meses / 3 then opera_preco_tabela(c.servico,1) * c.duracao_meses / 3 else c.valor_total end valor_integral from opera_contratos c where c.estado <> 'cancelado' and c.vendedor ilike 'Ana%' and c.tipo_venda in ('nova','cross_sell') ),
r1 as ( select e.lead_id, e.created_at::date dia from lead_events e join lead_stages s on s.id = e.to_stage_id join leads l on l.id = e.lead_id where e.type = 'stage' and s.name = 'R1' and e.author_id in (select id from ana) and l.client_id in (select id from clients where leads_internal) ),
k as ( select periodo_fim, sum(comissao) filter (where estado = 'pago') com_pago, sum(comissao) com_prev, max(base_rappel) base_rappel, max(base_rappel_pago) base_pago, sum(comissao) filter (where tipo_venda = 'recuperada') com_recuperadas from opera_comissoes group by 1 ),
r as ( select to_char(p.fim, 'YYYY-MM') chave, p.inicio::text inicio, p.fim::text fim, (p.fim < current_date) fechado, (current_date between p.inicio and p.fim) atual, round(15 * (p.fim - p.inicio + 1) / 7.0)::int obj_reunioes, (select count(distinct lead_id) from r1 where dia between p.inicio and p.fim)::int reunioes, (case when p.fim = date '2026-11-25' then 2 when p.fim = date '2026-12-25' then 5 else 6 end)::int obj_fechos, (select count(*) from vend where data_fecho between p.inicio and p.fim)::int fechos, 15000::float8 obj_vendas, (select coalesce(sum(valor_integral),0) from vend where data_fecho between p.inicio and p.fim)::float8 vendas, (select avg((modalidade = 1)::int) from vend where data_fecho between p.inicio and p.fim)::float8 pct_pif, coalesce(k.base_pago,0)::float8 base_recebida, coalesce(k.base_rappel,0)::float8 base_prevista, coalesce(k.com_pago,0)::float8 comissao_garantida, coalesce(k.com_prev,0)::float8 comissao_prevista, coalesce(k.com_recuperadas,0)::float8 comissao_recuperadas from p left join k on k.periodo_fim = p.fim )
select r.*, 0.10::float8 obj_conversao, (r.fechos::float8 / nullif(r.reunioes,0))::float8 conversao, 0.5::float8 obj_pif, (case when r.base_prevista > 24000 then 0.125 when r.base_prevista > 15000 then 0.11 else 0.10 end)::float8 taxa, (case when r.base_prevista > 24000 then '3 (12,5%)' when r.base_prevista > 15000 then '2 (11%)' else '1 (10%)' end) escalao, (case when r.base_prevista > 24000 then null when r.base_prevista > 15000 then 24000.01 - r.base_prevista else 15000.01 - r.base_prevista end)::float8 falta_proximo from r order by r.fim
$q$),
    'ana_comissoes', private.opera_j($q$
select pagamento_id::text id, cliente, servico, tipo_venda, numero, valor::float8 valor, base::float8 base, estado, dia::text dia, periodo_fim::text periodo_fim, taxa::float8 taxa, comissao::float8 comissao from opera_comissoes where periodo_fim between (date_trunc('month', current_date) - interval '1 month')::date and (date_trunc('month', current_date) + interval '3 months 24 days')::date order by periodo_fim, dia, cliente
$q$),
    'ana_bonus', private.opera_j($q$
with tri as ( select g::date i, (g + interval '3 months - 1 day')::date f from generate_series(date '2026-10-01', date_trunc('quarter', current_date) + interval '3 months', interval '3 months') g ),
cart as ( select distinct lower(cliente) cli from opera_contratos where vendedor ilike 'Ana%' and estado <> 'cancelado' ),
fim as ( select c.*, lower(c.cliente) cli from opera_contratos c where lower(c.cliente) in (select cli from cart) and c.estado <> 'cancelado' and not c.servico_unico ),
sat as ( select lower(cliente) cli, created_at::date dia, satisfacao_geral from feedback_respostas ),
r as ( select t.i, t.f, (select count(*) from fim where coalesce(terminado_em, data_fim) between t.i and t.f)::int packs_a_terminar, (select count(*) from fim where coalesce(terminado_em, data_fim) between t.i and t.f and renovacao = 'renovado')::int renovados, (select count(*) from fim where coalesce(terminado_em, data_fim) between t.i and t.f and renovacao = 'nao_renovou')::int nao_renovados, (select avg(satisfacao_geral) from sat where dia between t.i and t.f and cli in (select cli from cart))::float8 satisfacao, (select count(*) from sat where dia between t.i and t.f and cli in (select cli from cart))::int respostas from tri t )
select to_char(r.i, 'YYYY') || ' T' || extract(quarter from r.i) trimestre, r.i::text inicio, r.f::text fim, (current_date between r.i and r.f) atual, (r.f < current_date) fechado, r.packs_a_terminar, r.renovados, r.nao_renovados, r.packs_a_terminar - r.renovados - r.nao_renovados por_decidir, (r.renovados::float8 / nullif(r.renovados + r.nao_renovados, 0)) taxa_renovacao, r.satisfacao, r.respostas, (case when r.renovados + r.nao_renovados = 0 then null when r.renovados::float8 / (r.renovados + r.nao_renovados) >= 0.8 and r.satisfacao >= 8 then 500 when r.renovados::float8 / (r.renovados + r.nao_renovados) >= 0.8 then 250 else 0 end)::float8 bonus from r order by r.i
$q$));

  if v_nivel = 'comercial' then
    return ana || jsonb_build_object('nivel', 'comercial');
  end if;

  out := ana || jsonb_build_object('nivel', 'total', 'inicio', p_inicio, 'fim', p_fim);

  out := out || jsonb_build_object('resumo', private.opera_j($q$
with ativos as ( select * from opera_contratos_metricas where estado = 'ativo' and current_date between data_inicio and fim_previsto ), custos as ( select coalesce(sum(valor_mensal),0)::float8 total, coalesce(sum(valor_mensal) filter (where categoria='entrega'),0)::float8 entrega, coalesce(sum(valor_mensal) filter (where categoria='aquisicao'),0)::float8 aquisicao, coalesce(sum(valor_mensal) filter (where categoria='outros'),0)::float8 outros from opera_custos where tipo = 'mensal' and inicio <= current_date and (fim is null or fim >= current_date) ), pag as ( select p.* from opera_pagamentos p join opera_contratos c on c.id = p.contrato_id where p.estado <> 'cancelado' and c.estado <> 'cancelado' ), terminados as ( select count(*) filter (where renovacao='renovado') ren, count(*) filter (where renovacao='nao_renovou') nren from opera_contratos_metricas where data_fim < current_date or renovacao is not null ), r as ( select (select count(distinct lower(cliente)) from ativos)::int clientes_ativos, (select coalesce(sum(valor_total / duracao_meses),0) from ativos where not servico_unico)::float8 receita_mensal, (select count(*) from opera_contratos where estado='incompleto')::int contratos_incompletos, (select coalesce(sum(valor) filter (where estado='pago' and date_trunc('month', data_pagamento) = date_trunc('month', current_date)),0) from pag)::float8 recebido_mes, (select coalesce(sum(valor) filter (where date_trunc('month', data_prevista) = date_trunc('month', current_date)),0) from pag)::float8 previsto_mes, (select coalesce(sum(valor) filter (where estado='pendente' and data_prevista < current_date),0) from pag)::float8 em_atraso, (select count(*) filter (where estado='pendente' and data_prevista < current_date) from pag)::int n_em_atraso, (select coalesce(sum(valor) filter (where estado='pendente' and data_prevista between current_date and current_date + 30),0) from pag)::float8 receber_30d, (select valor from opera_saldo order by data desc, created_at desc limit 1)::float8 saldo, (select data from opera_saldo order by data desc, created_at desc limit 1)::text saldo_data, (select count(*) from ativos where data_fim <= current_date + 60 and renovacao is null and not servico_unico)::int renovacoes_60d, (select coalesce(sum(valor),0) from pag where extract(year from data_prevista) = 2027)::float8 receita_2027_contratada, (select coalesce(sum(valor) filter (where estado='pago'),0) from pag where extract(year from data_pagamento) = 2027)::float8 recebido_2027, (select case when ren + nren = 0 then null else ren::float8 / (ren + nren) end from terminados) taxa_renovacao, (select ren + nren from terminados)::int contratos_terminados ) select r.*, c.total custos_mes, c.entrega custos_entrega, c.aquisicao custos_aquisicao, c.outros custos_outros, r.receita_mensal - c.total margem_mes, case when r.receita_mensal > 0 then (r.receita_mensal - c.total) / r.receita_mensal end margem_pct, case when r.receita_mensal > 0 then c.entrega / r.receita_mensal end entrega_pct, case when r.receita_mensal > 0 then c.aquisicao / r.receita_mensal end aquisicao_pct, case when c.total > 0 and r.saldo is not null then r.saldo / c.total end meses_de_caixa, r.receita_mensal * 12 receita_anual_ritmo from r, custos c
$q$));

  out := out || jsonb_build_object('periodo', private.opera_j('with ' || par || $q$
, pl as ( select x.* from par cross join lateral opera_pnl(par.i, par.f) x ), ct as ( select c.*, c.fim_previsto fim_real, c.valor_total / c.duracao_meses mensal from opera_contratos_metricas c where c.estado in ('ativo','terminado') and c.valor_total is not null ), perdidos as ( select * from ct where fim_real < date '2099-12-31' and not servico_unico and coalesce(renovacao, '') <> 'renovado' ), lugar as ( select coalesce(sum(valor_mensal) filter (where descricao ilike 'Gestor de Leads%'),0) / nullif(count(*) filter (where descricao ilike 'Gestor de Leads%') * 8, 0) sa, coalesce(sum(valor_mensal) filter (where descricao ilike 'Back office%'),0) / nullif(count(*) filter (where descricao ilike 'Back office%') * 15, 0) bo from opera_custos, par where tipo = 'mensal' and inicio <= par.f and (fim is null or fim >= par.f) ), unid as ( select avg(ct.mensal) receita_cliente, avg(ct.mensal - case ct.servico when 'SA' then coalesce(lugar.sa,0) when 'BO' then coalesce(lugar.bo,0) when 'BUNDLE' then coalesce(lugar.sa,0) + coalesce(lugar.bo,0) else 0 end) margem_cliente from ct, lugar, par where ct.data_inicio <= par.f and ct.fim_real >= par.f and not ct.servico_unico ), pg as ( select p.*, c.modalidade from opera_pagamentos p join opera_contratos c on c.id = p.contrato_id where p.estado <> 'cancelado' and c.estado <> 'cancelado' ), ev as ( select e.lead_id, e.created_at::date dia, s.name fase from lead_events e join leads l on l.id = e.lead_id join lead_stages s on s.id = e.to_stage_id where e.type = 'stage' and l.client_id in (select id from clients where leads_internal) ), fecho as ( select lead_id, min(dia) dia from ev where fase in ('Closed','Em Onboarding','Entrega de serviço') group by 1 ), novos as ( select c.* from opera_contratos c, par where c.origem in ('automatico','manual') and c.estado <> 'cancelado' and c.data_fecho between par.i and par.f ), term as ( select count(*) filter (where renovacao = 'renovado') ren, count(*) filter (where renovacao = 'nao_renovou') nren from opera_contratos_metricas where renovacao is not null ), r as ( select par.i::text inicio, par.f::text fim, (par.f - par.i + 1)::int dias, (select receita from pl)::float8 receita, (select faturacao from pl)::float8 faturacao, (select coalesce(sum(valor),0) from pg where data_prevista between par.i and par.f and modalidade = 1)::float8 faturacao_pif, (select coalesce(sum(valor),0) from pg where data_prevista between par.i and par.f and modalidade > 1)::float8 faturacao_mensal, (select caixa from pl)::float8 caixa, (select coalesce(sum(valor),0) from pg where estado = 'pago' and data_pagamento between par.i and par.f and modalidade = 1)::float8 caixa_pif, (select coalesce(sum(valor),0) from pg where estado = 'pago' and data_pagamento between par.i and par.f and modalidade > 1)::float8 caixa_mensal, (select coalesce(sum(valor),0) from pg where estado = 'pendente' and data_prevista between par.i and par.f)::float8 por_receber, (select coalesce(sum(mensal),0) from ct where data_inicio <= par.i and fim_real >= par.i and not servico_unico)::float8 mrr_inicio, (select coalesce(sum(mensal),0) from ct where data_inicio <= par.f and fim_real >= par.f and not servico_unico)::float8 mrr_fim, (select count(distinct lower(cliente)) from ct where data_inicio <= par.i and fim_real >= par.i)::int clientes_inicio, (select count(distinct lower(cliente)) from ct where data_inicio <= par.f and fim_real >= par.f)::int clientes_fim, (select count(*) from novos)::int contratos_novos, (select coalesce(sum(valor_total),0) from novos)::float8 vendas_novas, (select avg((modalidade = 1)::int) from novos where modalidade is not null)::float8 pct_pif_vendas, (select avg((servico = 'BUNDLE')::int) from novos where servico is not null)::float8 pct_bundle, (select avg(valor_total) from novos)::float8 ticket_medio, (select coalesce(sum(valor_total / duracao_meses),0) from novos where valor_total is not null and not servico_unico)::float8 mrr_novo, (select count(*) from opera_contratos where origem = 'renovacao' and estado <> 'cancelado' and data_inicio between par.i and par.f)::int renovacoes, (select count(distinct lower(cliente)) from perdidos where fim_real between par.i and par.f)::int clientes_perdidos, (select coalesce(sum(mensal),0) from perdidos where fim_real between par.i and par.f)::float8 mrr_perdido, (select custos_entrega from pl)::float8 custos_entrega, (select custos_aquisicao from pl)::float8 custos_aquisicao, (select custos_outros from pl)::float8 custos_outros, (select count(*) from novos)::int clientes_novos_cac, (select count(distinct lead_id) from ev where fase = 'R1' and dia between par.i and par.f)::int r1, (select count(distinct lead_id) from ev where fase = 'R2' and dia between par.i and par.f)::int r2, (select count(distinct lead_id) from ev where fase = 'Em decisão' and dia between par.i and par.f)::int em_decisao, (select count(*) from fecho where dia between par.i and par.f)::int fechos, (select receita_cliente from unid)::float8 receita_cliente, (select margem_cliente from unid)::float8 margem_cliente, (select sa from lugar)::float8 custo_lugar_sa, (select bo from lugar)::float8 custo_lugar_bo, (select case when ren + nren >= 5 then ren::float8 / (ren + nren) else 0.8 end from term) taxa_renovacao_usada, (select ren + nren >= 5 from term) taxa_real, (select (ren + nren)::int from term) decisoes_renovacao from par ), d as ( select r.*, r.custos_entrega + r.custos_aquisicao + r.custos_outros custos_total, r.receita - r.custos_entrega margem_bruta_periodo, (r.receita - r.custos_entrega) / nullif(r.receita, 0) margem_bruta_pct, r.receita - r.custos_entrega - r.custos_aquisicao - r.custos_outros resultado, (r.receita - r.custos_entrega - r.custos_aquisicao - r.custos_outros) / nullif(r.receita, 0) resultado_pct, r.r2::float8 / nullif(r.r1, 0) conv_r1_r2, r.fechos::float8 / nullif(r.r2, 0) conv_r2_fecho, r.fechos::float8 / nullif(r.r1, 0) conv_r1_fecho, r.clientes_perdidos::float8 / nullif(r.clientes_inicio, 0) churn_periodo, r.clientes_perdidos::float8 / nullif(r.clientes_inicio, 0) / (r.dias / 30.4375) churn_mensal, r.mrr_perdido / nullif(r.mrr_inicio, 0) churn_mrr, r.custos_aquisicao / nullif(r.clientes_novos_cac, 0) cac, r.margem_cliente / nullif(r.receita_cliente, 0) margem_bruta, 3 / nullif(1 - r.taxa_renovacao_usada, 0) vida_media_meses from r ) select d.*, d.margem_cliente * d.vida_media_meses ltv, d.margem_cliente * d.vida_media_meses / nullif(d.cac, 0) ltv_cac, d.cac / nullif(d.margem_cliente, 0) payback_meses from d
$q$));

  out := out || jsonb_build_object('pnl_periodo', private.opera_j('with ' || par || $q$
, x as ( select p.* from par cross join lateral opera_pnl(par.i, par.f) p ) select receita::float8 receita, receita_pipeline::float8 receita_pipeline, custos_entrega::float8 custos_entrega, custos_aquisicao::float8 custos_aquisicao, custos_outros::float8 custos_outros, (custos_entrega + custos_aquisicao + custos_outros)::float8 custos_total, (receita - custos_entrega)::float8 margem_bruta, ((receita - custos_entrega) / nullif(receita, 0))::float8 margem_bruta_pct, (receita_pipeline - custos_entrega)::float8 margem_bruta_pipeline, ((receita_pipeline - custos_entrega) / nullif(receita_pipeline, 0))::float8 margem_bruta_pipeline_pct, (receita - custos_entrega - custos_aquisicao - custos_outros)::float8 resultado, ((receita - custos_entrega - custos_aquisicao - custos_outros) / nullif(receita, 0))::float8 resultado_pct, (receita_pipeline - custos_entrega - custos_aquisicao - custos_outros)::float8 resultado_pipeline, ((receita_pipeline - custos_entrega - custos_aquisicao - custos_outros) / nullif(receita_pipeline, 0))::float8 resultado_pipeline_pct, faturacao::float8 faturacao, caixa::float8 caixa from x
$q$));

  out := out || jsonb_build_object('pnl_mensal', private.opera_j($q$
with meses as (select generate_series(date_trunc('month', current_date) - interval '5 months', date_trunc('month', current_date) + interval '2 months', interval '1 month')::date m), p as ( select m, x.* from meses cross join lateral opera_pnl(m, (m + interval '1 month - 1 day')::date) x ) select to_char(m, 'YYYY-MM') mes, (m > date_trunc('month', current_date)::date) futuro, receita::float8 receita, custos_entrega::float8 custos_entrega, (receita - custos_entrega)::float8 margem_bruta, ((receita - custos_entrega) / nullif(receita, 0))::float8 margem_bruta_pct, custos_aquisicao::float8 custos_aquisicao, custos_outros::float8 custos_outros, (receita - custos_entrega - custos_aquisicao - custos_outros)::float8 resultado, ((receita - custos_entrega - custos_aquisicao - custos_outros) / nullif(receita, 0))::float8 resultado_pct, receita_pipeline::float8 receita_pipeline, (receita_pipeline - custos_entrega - custos_aquisicao - custos_outros)::float8 resultado_pipeline, ((receita_pipeline - custos_entrega - custos_aquisicao - custos_outros) / nullif(receita_pipeline, 0))::float8 resultado_pipeline_pct, faturacao::float8 faturacao, caixa::float8 caixa from p order by m
$q$));

  out := out || jsonb_build_object('fluxo', private.opera_j($q$
with meses as (select generate_series(date_trunc('month', current_date) - interval '2 months', date_trunc('month', current_date) + interval '5 months', interval '1 month')::date m) select to_char(m, 'YYYY-MM') mes, x.faturacao::float8 a_receber, x.caixa::float8 recebido, (x.custos_entrega + x.custos_aquisicao + x.custos_outros)::float8 custos from meses cross join lateral opera_pnl(m, (m + interval '1 month - 1 day')::date) x order by m
$q$));

  out := out || jsonb_build_object('contratos', private.opera_j($q$
select c.id::text id, c.cliente, coalesce(s.name, 'Manual') fase, (c.id in (select id from opera_contratos_metricas)) conta, coalesce(c.servico, '?') servico, c.modalidade, c.valor_total::float8 valor_total, c.data_inicio::text data_inicio, c.data_fim::text data_fim, c.estado, coalesce(c.renovacao, '') renovacao, c.origem, c.vendedor, coalesce(sum(p.valor) filter (where p.estado='pago'),0)::float8 pago, coalesce(sum(p.valor) filter (where p.estado='pendente'),0)::float8 pendente, coalesce(sum(p.valor) filter (where p.estado='pendente' and p.data_prevista < current_date),0)::float8 em_atraso, (c.data_fim - current_date)::int dias_para_fim from opera_contratos c left join leads l on l.id = c.lead_id left join lead_stages s on s.id = l.stage_id left join opera_pagamentos p on p.contrato_id = c.id where c.estado <> 'cancelado' and (c.estado in ('ativo','incompleto') or c.data_fim >= current_date - 30) group by c.id, s.name order by (c.id in (select id from opera_contratos_metricas)) desc, c.estado = 'incompleto' desc, c.data_fim
$q$));

  out := out || jsonb_build_object('contratos_pipeline', private.opera_j('with ' || par || $q$
select c.id::text id, c.cliente, s.name fase, coalesce(c.servico, '?') servico, c.estado, c.modalidade, c.valor_total::float8 valor_total, (c.valor_total / c.duracao_meses)::float8 mensal, c.data_fecho::text data_fecho, c.data_inicio::text data_inicio, coalesce((select sum(p.valor) from opera_pagamentos p where p.contrato_id = c.id and p.estado = 'pago'), 0)::float8 recebido from opera_contratos c join leads l on l.id = c.lead_id join lead_stages s on s.id = l.stage_id, par where s.name in ('Closed', 'Em Onboarding') and c.estado <> 'cancelado' and (c.data_fecho is null or c.data_fecho between par.i and par.f) order by s.position, c.data_fecho nulls last, c.cliente
$q$));

  out := out || jsonb_build_object('capacidade', private.opera_j($q$
with carga as ( select c.id, greatest(1, coalesce((select count(distinct (e.lead_id, e.created_at::date))::float8 / greatest(count(distinct e.created_at::date),1) from lead_events e join leads l on l.id = e.lead_id where e.type = 'call' and e.created_at >= now() - interval '30 days' and l.client_id = c.id),0) / 25) slots from clients c where c.leads_enabled and not c.leads_internal ), pessoas as ( select count(*) filter (where descricao ilike 'Gestor de Leads%')::int gestores, count(*) filter (where descricao ilike 'Back office%')::int pessoas_bo from opera_custos where tipo = 'mensal' and inicio <= current_date and (fim is null or fim >= current_date) ), bo as ( select count(distinct lower(cliente))::int clientes_bo from opera_contratos_metricas where estado = 'ativo' and servico in ('BO','BUNDLE') and current_date between data_inicio and fim_previsto ) select (select count(*) from carga)::int clientes_sa_com_leads, (select sum(slots) from carga)::float8 slots_usados, p.gestores, (p.gestores * 8)::int slots_disponiveis, case when p.gestores > 0 then (select sum(slots) from carga) / (p.gestores * 8) end ocupacao_sa, b.clientes_bo, p.pessoas_bo, (p.pessoas_bo * 15)::int capacidade_bo, case when p.pessoas_bo > 0 then b.clientes_bo::float8 / (p.pessoas_bo * 15) end ocupacao_bo from pessoas p, bo b
$q$));

  out := out || jsonb_build_object('operacao', private.opera_j('with ' || par || $q$
, cl as (select id, name from clients where leads_enabled and not leads_internal), novas as ( select l.client_id, l.id, extract(epoch from (l.first_call_at - l.created_at)) / 60 ttl_min from leads l, par where l.client_id in (select id from cl) and l.created_at::date between par.i and par.f and coalesce(l.entry_stage,'') <> 'bd' ), ch as ( select l.client_id, e.lead_id, e.created_at::date dia, coalesce((e.meta->>'answered')::boolean, false) atendida from lead_events e join leads l on l.id = e.lead_id, par where e.type = 'call' and e.created_at::date between par.i and par.f and l.client_id in (select id from cl) ), rec as ( select l.client_id, count(distinct l.id) n from leads l join lead_events e on e.lead_id = l.id join lead_stages s on s.id = e.to_stage_id, par where l.entry_stage = 'bd' and e.type = 'stage' and s.key = 'qualificada' and e.created_at::date between par.i and par.f group by 1 ), tar as ( select l.client_id, count(*) n from lead_tasks t join leads l on l.id = t.lead_id where t.done_at is null and t.canceled_at is null and t.due_at < now() group by 1 ), dia as ( select client_id, count(distinct (lead_id, dia))::float8 / greatest(count(distinct dia),1) por_dia from ch group by 1 ) select cl.name cliente, (select count(*) from novas n where n.client_id = cl.id)::int leads_novas_30d, (select percentile_cont(0.5) within group (order by ttl_min) from novas n where n.client_id = cl.id and ttl_min is not null)::float8 ttl_mediano_min, (select case when count(*) = 0 then null else (count(*) filter (where ttl_min <= 15))::float8 / count(*) end from novas n where n.client_id = cl.id) pct_ttl_15, (select count(*) from ch where ch.client_id = cl.id)::int chamadas_30d, (select case when count(*) = 0 then null else (count(*) filter (where atendida))::float8 / count(*) end from ch where ch.client_id = cl.id) taxa_atendimento, coalesce((select n from rec where rec.client_id = cl.id),0)::int recuperadas_30d, coalesce((select n from tar where tar.client_id = cl.id),0)::int tarefas_atrasadas, coalesce((select por_dia from dia where dia.client_id = cl.id),0)::float8 leads_trabalhadas_dia, greatest(1, coalesce((select por_dia from dia where dia.client_id = cl.id),0) / 25)::float8 carga_slots from cl order by leads_trabalhadas_dia desc
$q$));

  out := out || jsonb_build_object('pipeline', private.opera_j($q$
with op as (select id from clients where leads_internal), st as ( select s.id, s.name, s.position from lead_stages s where s.client_id is null or s.client_id in (select id from op) ) select st.name fase, st.position::float8 ordem, (select count(*) from leads l where l.stage_id = st.id and l.client_id in (select id from op))::int leads_agora, (select count(distinct e.lead_id) from lead_events e join leads l on l.id = e.lead_id where e.type = 'stage' and e.to_stage_id = st.id and l.client_id in (select id from op) and e.created_at >= now() - interval '30 days')::int entradas_30d from st where st.name not in ('Nova Lead Meta','Nova lead imóveis') order by st.position
$q$));

  out := out || jsonb_build_object('vendas_mensais', private.opera_j($q$
with meses as (select generate_series(date_trunc('month', current_date) - interval '5 months', date_trunc('month', current_date), interval '1 month')::date mes) select to_char(m.mes, 'YYYY-MM') mes, count(c.id) filter (where c.origem <> 'renovacao')::int novos, coalesce(sum(c.valor_total) filter (where c.origem <> 'renovacao'),0)::float8 valor_novos, count(c.id) filter (where c.origem = 'renovacao')::int renovacoes, coalesce(sum(c.valor_total) filter (where c.origem = 'renovacao'),0)::float8 valor_renovacoes, count(c.id) filter (where c.modalidade = 1)::int integrais, count(c.id) filter (where c.servico = 'BUNDLE')::int bundles from meses m left join opera_contratos c on date_trunc('month', coalesce(c.data_fecho, c.data_inicio)) = m.mes and c.estado <> 'cancelado' group by m.mes order by m.mes
$q$));

  out := out || jsonb_build_object('funil_semanal', private.opera_j($q$
with ev as ( select e.lead_id, e.created_at, s.name fase from lead_events e join leads l on l.id = e.lead_id join lead_stages s on s.id = e.to_stage_id where e.type = 'stage' and l.client_id in (select id from clients where leads_internal) ), fecho as ( select lead_id, min(created_at) created_at from ev where fase in ('Closed','Em Onboarding','Entrega de serviço') group by 1 ), sem as ( select generate_series(date_trunc('week', current_date) - interval '7 weeks', date_trunc('week', current_date), interval '1 week')::date semana ) select s.semana::text semana, (select count(distinct lead_id) from ev where fase = 'R1' and date_trunc('week', created_at)::date = s.semana)::int r1, (select count(distinct lead_id) from ev where fase = 'R2' and date_trunc('week', created_at)::date = s.semana)::int r2, (select count(*) from fecho where date_trunc('week', created_at)::date = s.semana)::int fechos from sem s order by s.semana
$q$));

  out := out || jsonb_build_object('comercial_pessoas', private.opera_j('with ' || par || $q$
, ev as ( select e.lead_id, e.created_at, e.author_id, s.name fase from lead_events e join leads l on l.id = e.lead_id join lead_stages s on s.id = e.to_stage_id, par where e.type = 'stage' and l.client_id in (select id from clients where leads_internal) and e.created_at::date between par.i and par.f ), fecho as ( select distinct on (lead_id) lead_id, author_id from ev where fase in ('Closed','Em Onboarding','Entrega de serviço') order by lead_id, created_at ) select coalesce(p.full_name, 'Sem autor') pessoa, (select count(distinct lead_id) from ev where fase = 'R1' and ev.author_id is not distinct from a.author_id)::int r1, (select count(distinct lead_id) from ev where fase = 'R2' and ev.author_id is not distinct from a.author_id)::int r2, (select count(*) from fecho where fecho.author_id is not distinct from a.author_id)::int fechos from (select distinct author_id from ev where fase in ('R1','R2','Em decisão','Closed','Em Onboarding','Entrega de serviço')) a left join profiles p on p.id = a.author_id order by 2 desc
$q$));

  out := out || jsonb_build_object('ttl_semanal', private.opera_j($q$
with sem as (select generate_series(date_trunc('week', current_date) - interval '7 weeks', date_trunc('week', current_date), interval '1 week')::date semana), novas as ( select date_trunc('week', l.created_at)::date semana, extract(epoch from (l.first_call_at - l.created_at)) / 60 ttl_min from leads l join clients c on c.id = l.client_id where not c.leads_internal and l.created_at >= date_trunc('week', current_date) - interval '7 weeks' and coalesce(l.entry_stage,'') <> 'bd' ) select s.semana::text semana, count(n.semana)::int leads_novas, (percentile_cont(0.5) within group (order by n.ttl_min))::float8 ttl_mediano_min, case when count(n.semana) = 0 then null else (count(*) filter (where n.ttl_min <= 15))::float8 / count(n.semana) end pct_ttl_15 from sem s left join novas n on n.semana = s.semana group by s.semana order by s.semana
$q$));

  out := out || jsonb_build_object('funil_lista', private.opera_j('with ' || par || $q$
, ev as ( select e.lead_id, e.created_at::date dia, s.name fase from lead_events e join leads l on l.id = e.lead_id join lead_stages s on s.id = e.to_stage_id where e.type = 'stage' and l.client_id in (select id from clients where leads_internal) ), lista as ( select 'R1' etapa, lead_id, min(dia) dia from ev, par where fase = 'R1' and dia between par.i and par.f group by lead_id union all select 'R2', lead_id, min(dia) from ev, par where fase = 'R2' and dia between par.i and par.f group by lead_id union all select 'Fecho', lead_id, dia from ( select lead_id, min(dia) dia from ev where fase in ('Closed','Em Onboarding','Entrega de serviço') group by lead_id ) x, par where x.dia between par.i and par.f ) select lista.etapa || ':' || lista.lead_id::text chave, lista.etapa, l.id::text lead_id, l.name cliente, lista.dia::text dia, s.name fase_atual, c.servico, c.valor_total::float8 valor_total from lista join leads l on l.id = lista.lead_id left join lead_stages s on s.id = l.stage_id left join lateral ( select servico, valor_total from opera_contratos oc where oc.lead_id = lista.lead_id and oc.estado <> 'cancelado' order by oc.created_at desc limit 1 ) c on true order by lista.etapa, lista.dia desc, l.name
$q$));

  out := out || jsonb_build_object('unit_servico', private.opera_j('with ' || par || $q$
, ct as ( select c.*, c.valor_total / c.duracao_meses mensal from opera_contratos_metricas c, par where c.estado in ('ativo','terminado') and c.valor_total is not null and not c.servico_unico and c.data_inicio <= par.f and c.fim_previsto >= par.f ), lugar as ( select coalesce(sum(valor_mensal) filter (where descricao ilike 'Gestor de Leads%'),0) / nullif(count(*) filter (where descricao ilike 'Gestor de Leads%') * 8, 0) sa, coalesce(sum(valor_mensal) filter (where descricao ilike 'Back office%'),0) / nullif(count(*) filter (where descricao ilike 'Back office%') * 15, 0) bo from opera_custos, par where tipo = 'mensal' and inicio <= par.f and (fim is null or fim >= par.f) ), term as ( select count(*) filter (where renovacao = 'renovado') ren, count(*) filter (where renovacao = 'nao_renovou') nren from opera_contratos_metricas where renovacao is not null ), taxa as ( select case when ren + nren >= 5 then ren::float8 / (ren + nren) else 0.8 end t from term ), novos as ( select c.* from opera_contratos c, par where c.origem in ('automatico','manual') and c.estado <> 'cancelado' and c.data_fecho between par.i and par.f ), com as ( select c.servico, sum(k.custo_empresa) v from opera_comissoes k join opera_contratos c on c.id = k.contrato_id, par where k.dia between par.i and par.f group by 1 ), aq as ( select x.custos_aquisicao total, coalesce((select sum(custo_empresa) from opera_comissoes, par where dia between par.i and par.f),0) comissoes from par cross join lateral opera_pnl(par.i, par.f) x ), serv as ( select * from (values ('SA','OPERA SA',1),('BO','OPERA BO',2),('BUNDLE','Bundle SA + BO',3),('GLOBAL','Global',4)) v(k,nome,ordem) ), lin as ( select s.k, s.nome, s.ordem, (select count(distinct lower(cliente)) from ct where s.k = 'GLOBAL' or ct.servico = s.k)::int clientes, (select avg(mensal) from ct where s.k = 'GLOBAL' or ct.servico = s.k)::float8 receita_cliente, (select avg(case ct.servico when 'SA' then coalesce(l.sa,0) when 'BO' then coalesce(l.bo,0) when 'BUNDLE' then coalesce(l.sa,0)+coalesce(l.bo,0) else 0 end) from ct, lugar l where s.k = 'GLOBAL' or ct.servico = s.k)::float8 custo_lugar, (select count(*) from novos where s.k = 'GLOBAL' or novos.servico = s.k)::int novos, (select coalesce(sum(v),0) from com where s.k = 'GLOBAL' or com.servico = s.k)::float8 comissoes from serv s ), d as ( select lin.*, (select t from taxa)::float8 taxa_renovacao, (lin.receita_cliente - lin.custo_lugar)::float8 margem_cliente, (3 / (1 - (select t from taxa)))::float8 vida_meses, ((select total - comissoes from aq) * lin.novos / nullif((select count(*) from novos),0))::float8 fixos_alocados from lin ), e as ( select d.*, (d.margem_cliente * d.vida_meses)::float8 ltv, ((coalesce(d.fixos_alocados,0) + d.comissoes) / nullif(d.novos,0))::float8 cac from d ) select e.k, e.nome, e.clientes, e.receita_cliente, e.custo_lugar, e.margem_cliente, e.taxa_renovacao, e.vida_meses, e.ltv, e.novos, e.comissoes, e.fixos_alocados, e.cac, (e.ltv / nullif(e.cac,0))::float8 ltv_cac, (e.cac / nullif(e.margem_cliente,0))::float8 payback_meses from e order by e.ordem
$q$));

  return out;
end $fn$;

